40	}
41	
42	// frameLog is the shared append-only frame writer behind the event, incident,
43	// and metric logs. It owns the frame layout, torn-tail recovery, and the
44	// poison-on-failure write path; each concrete log supplies only its own
45	// payload encoding and content validation, so the durability rule lives in
46	// exactly one place.
47	type frameLog struct {
48		mu       sync.Mutex
49		file     *os.File
50		dir      string
51		noun     string // the log's name in error messages: "event", "incident", "metrics"
52		unit     string // what one frame holds: "batch", "incident record", "metric batch"
53		poisoned bool
54	}
