func postMetrics(t *testing.T, p *serverProc, body string) map[string]int {
	t.Helper()
	status, raw := httpDo(t, http.MethodPost, "http://"+p.addr+"/metrics", body)
	if status >= 400 {
		t.Fatalf("POST /metrics status %d: %s", status, raw)
	}
