const sampleMetrics = `{"samples":[
	{"id":"m1","service":"gateway","name":"requests","at":"2026-10-01T10:00:00Z","value":100},
	{"id":"m2","service":"gateway","name":"requests","at":"2026-10-01T10:01:00Z","value":105}
