	status, got := metricAggregate(t, p2,
		"?name=requests&since=2026-10-01T10:00:00Z&until=2026-10-01T10:02:00Z&step=60")
	if status != http.StatusOK {
		t.Fatalf("aggregate after restart: %d %v", status, got)
